<?php
declare(strict_types=1);
const DUTY_ROLES=['lead'=>'全体統括','deputy'=>'副統括','accounting'=>'会計担当','system'=>'システム担当','publicity'=>'広報担当','venue'=>'会場担当','planning'=>'企画運営担当','guest'=>'恩師・来賓対応','support'=>'応援者・協力者対応','reception'=>'受付担当','mc'=>'司会','photography'=>'写真撮影','recording'=>'記録担当','reunion'=>'二次会担当','accessibility'=>'案内・配慮対応','other'=>'その他'];
const DUTY_STATUS=['planned'=>'依頼・調整中','active'=>'担当決定','done'=>'完了','inactive'=>'担当解除'];
function saveDuty(array $u,array $d):int {
 global $db;requirev($u['role']==='owner','担当の設定は管理者が行います。');$id=(int)($d['id']??0);$record=$id?one('SELECT * FROM duties WHERE id=?',[$id]):null;if($id)requirev((bool)$record,'担当記録がありません。');if($record)requirev((int)($d['revision']??0)===(int)$record['revision'],'他の操作で更新されています。画面を開き直してください。');
 $role=(string)($d['roleKey']??'');requirev(isset(DUTY_ROLES[$role]),'担当を選択してください。');$kind=(string)($d['kind']??'');requirev(in_array($kind,['member','external'],true),'担当者の区分を選択してください。');$uid=$kind==='member'?(int)($d['userId']??0):null;if($kind==='member')requirev((bool)publicUser($uid),'登録者を選択してください。');
 $text=static function(string $key,int $max,bool $required=false)use($d):string{$v=trim((string)($d[$key]??''));requirev(mb_strlen($v)<=$max&&(!$required||$v!==''),'必須項目と文字数を確認してください。');return $v;};
 $status=(string)($d['status']??'active');requirev(isset(DUTY_STATUS[$status]),'担当状況を選択してください。');$cl=(string)($d['class']??'0');requirev((bool)preg_match('/^(?:[0-9]|10)$/D',$cl),'対象クラスを確認してください。');$due=$text('dueDate',10);if($due!=='')requirev(datev($due)===$due,'対応予定日を確認してください。');$before=$record?obj($record['data_json']):null;
 $x=['id'=>$id,'revision'=>($record?(int)$record['revision']:0)+1,'roleKey'=>$role,'customRole'=>$role==='other'?$text('customRole',100,true):'','kind'=>$kind,'userId'=>$uid,'externalName'=>$kind==='external'?$text('externalName',100,true):'','class'=>(int)$cl,'scope'=>$text('scope',200),'description'=>$text('description',2000),'contact'=>$kind==='external'?$text('contact',300):'','note'=>$text('note',2000),'status'=>$status,'dueDate'=>$due,'created'=>$before['created']??nowv(),'updated'=>nowv()];$reason=reasonv($d);
 if($record)q('UPDATE duties SET user_id=?,revision=?,data_json=? WHERE id=?',[$uid,$x['revision'],jsonv($x),$id]);else {q('INSERT INTO duties (user_id,revision,data_json) VALUES (?,?,?)',[$uid,1,jsonv($x)]);$id=(int)$db->lastInsertId();$x['id']=$id;q('UPDATE duties SET data_json=? WHERE id=?',[jsonv($x),$id]);}
 logv((int)$u['id'],'担当を設定','duty:'.$id,$before,$x,$reason);return $id;
}
function dutyRecords():array{return array_map(fn($r)=>[...obj($r['data_json']),'id'=>(int)$r['id'],'revision'=>(int)$r['revision']],all('SELECT * FROM duties ORDER BY id'));}
function dutyRows(array $u):array {
 adminInquiry($u);$rows=[];foreach(all('SELECT c.*,u.name,r.class_no AS person_class FROM class_contacts c JOIN users u ON u.id=c.user_id LEFT JOIN registrations r ON r.user_id=u.id ORDER BY c.class_no,c.position_no,c.id') as $c)$rows[]=['id'=>'c'.$c['id'],'source'=>'class','roleKey'=>'class','label'=>'クラス幹事','userId'=>(int)$c['user_id'],'kind'=>'member','class'=>(int)$c['class_no'],'personClass'=>(int)($c['person_class']??0),'status'=>'active','scope'=>'表示順 '.$c['position_no'],'description'=>'クラスの連絡・登録確認','dueDate'=>'','name'=>$c['name']];
 foreach(dutyRecords() as $x){$p=$x['userId']?publicUser((int)$x['userId']):null;$r=$p?registrationFor((int)$p['id']):null;$rows[]=[...$x,'source'=>'duty','label'=>$x['roleKey']==='other'?$x['customRole']:DUTY_ROLES[$x['roleKey']],'name'=>$x['kind']==='external'?$x['externalName']:($p['name']??'未登録'),'personClass'=>(int)($r['class_no']??0)];}return $rows;
}
function filterDuties(array $rows,array $f,int $uid):array {$query=mb_strtolower(trim((string)($f['q']??'')));return array_values(array_filter($rows,fn($x)=>($query===''||str_contains(mb_strtolower($x['name'].' '.$x['label'].' '.$x['scope'].' '.$x['description']),$query))&&(empty($f['role'])||$x['roleKey']===$f['role'])&&(empty($f['class'])||$x['class']===(int)$f['class']||$x['personClass']===(int)$f['class'])&&(empty($f['kind'])||$x['kind']===$f['kind'])&&(empty($f['status'])||$x['status']===$f['status'])&&(($f['mine']??'')!=='yes'||$x['userId']===$uid)));}
function ownDuties(int $uid):array {
 $rows=[];foreach(all('SELECT * FROM class_contacts WHERE user_id=? ORDER BY class_no,position_no',[$uid]) as $c)$rows[]=['label'=>'クラス幹事','scope'=>'3年'.$c['class_no'].'組','description'=>'クラスの連絡・登録確認','status'=>'active','dueDate'=>''];foreach(dutyRecords() as $x)if($x['userId']===$uid&&$x['kind']==='member'&&$x['status']!=='inactive')$rows[]=['label'=>$x['roleKey']==='other'?$x['customRole']:DUTY_ROLES[$x['roleKey']],'scope'=>$x['scope'],'description'=>$x['description'],'status'=>$x['status'],'dueDate'=>$x['dueDate']];return $rows;
}
function dutyCSV(array $u,array $f):array {return array_map(fn($x)=>['担当'=>$x['label'],'担当者'=>$x['name'],'区分'=>$x['kind']==='external'?'外部協力者':'登録者','対象クラス'=>$x['class']?'3年'.$x['class'].'組':'全体','担当範囲'=>$x['scope'],'担当内容'=>$x['description'],'状況'=>DUTY_STATUS[$x['status']],'対応予定日'=>$x['dueDate']],filterDuties(dutyRows($u),$f,(int)$u['id']));}
